  ('475ce925-ba61-4a70-b719-867acd5b98b5', '01bce23e-0bc9-4328-ae9b-0082f5917890', $$inleiding: belastingen buiten beschouwing; Levi bestudeert het jaarverslag van Aegon$$,
   $$bedrijfseconomie-havo-2025-i-levi-context1.png$$,
   $$In deze opgave blijven belastingen buiten beschouwing.
Levi wil gaan beleggen in aandelen of obligaties van Aegon. Hij bestudeert het jaarverslag van Aegon.
De verzekeraar geeft in het jaarverslag aan tevreden te zijn over het resultaat en de hoogte van de kengetallen liquiditeit en rentabiliteit van het eigen vermogen. De solvabiliteit daarentegen is wel verslechterd.$$, 'inline'),
  ('188df395-125e-4c96-a913-d8abd2b5aac0', '01bce23e-0bc9-4328-ae9b-0082f5917890', $$inleiding balans Aegon$$,
   $$bedrijfseconomie-havo-2025-i-levi-context2.png$$,
   $$De balans van 2022 van Aegon is hieronder weergegeven:$$, 'inline'),
